/**
 * Public Course Lab publications. Authored bundles live in independent JSON
 * files, generated by the authenticated GitHub staff publisher.
 * Importing this module NEVER fetches or advertises non-published lessons.
 */
import {validateLearnBundle} from './ns-learn-engine-v2.mjs';
export const PUBLISHED_COURSE_BUNDLES=Object.freeze({});
const bundles=new Map();
let index={version:1,courses:{}},indexLoaded=false,inflight=null;
const base=new URL('./learn-content/',import.meta.url);
const validId=id=>/^[a-z0-9][a-z0-9-]{0,119}$/.test(String(id||''));
export const getLearnIndex=()=>index;
export const getLearnContent=id=>bundles.get(id)||PUBLISHED_COURSE_BUNDLES[id]||null;
export const hasPublishedLearnCourse=id=>!!index.courses[id]||!!PUBLISHED_COURSE_BUNDLES[id];
export async function loadPublishedLearnIndex({refresh=false}={}){
 if(indexLoaded&&!refresh)return index;
 if(inflight)return inflight;
 if(typeof fetch!=='function')return index;
 inflight=(async()=>{
  const response=await fetch(new URL('index.json',base),{cache:'no-store'});
  if(!response.ok)throw Error('Course availability could not be loaded ('+response.status+').');
  const data=await response.json();
  if(data?.version!==1||!data.courses||typeof data.courses!=='object'||Array.isArray(data.courses))throw Error('Invalid published course index.');
  const allowed={};
  for(const [id,record] of Object.entries(data.courses)){
   if(validId(id)&&Number.isInteger(record?.version)&&record.version>=1)allowed[id]={version:record.version};
  }
  index={version:1,courses:allowed};indexLoaded=true;
  for(const [id,bundle] of bundles)if(bundle.version!==allowed[id]?.version)bundles.delete(id);
  return index;
 })().finally(()=>{inflight=null;});
 return inflight;
}
export async function loadPublishedLearnBundle(id){
 if(!validId(id))return null;
 await loadPublishedLearnIndex();
 const record=index.courses[id];
 if(!record)return PUBLISHED_COURSE_BUNDLES[id]||null;
 const cached=bundles.get(id);
 if(cached?.version===record.version)return cached;
 const url=new URL('courses/'+id+'.json',base);
 url.searchParams.set('v',String(record.version));
 const response=await fetch(url,{cache:'no-store'});
 if(!response.ok)throw Error('Published course could not be downloaded ('+response.status+').');
 const bundle=await response.json();
 const errors=validateLearnBundle(bundle,id);
 if(errors.length||bundle.version!==record.version)throw Error('Published course failed validation: '+errors.slice(0,3).join('; '));
 bundles.set(id,bundle);
 return bundle;
}
